"""Recover one closed separator boundary from exact pavement ownership.

This branch requires two once-owned member corridors between two distinct
terminal patch owners. It selects an existing boundary component through four
semantic inner-profile corner identities. It never invents edges, samples a
replacement boundary or identifies grass from the height of nearby vertices.
More general split separators and free/overlapping ends need other branches.
"""
import bpy
from . import curved_junction_nodes as boundary
from . import curved_patch_provider_nodes as providers
c = boundary.c
NAME = 'Prochitecture Streets / Original separator boundary v1'


def _edges(g, mesh, selected):
    node = g.node('GeometryNodeSeparateGeometry'); node.domain = 'EDGE'
    g.bind(mesh, node.inputs['Geometry']); g.bind(selected, node.inputs['Selection'])
    return c.V(g, node.outputs['Selection'])


def captured_wire(g, pavement, *, original_edge=False):
    """Capture original indices/face owners; materialize tags only on the wire.

    Capture edge ownership while adjacent faces still exist, just as in the
    original full-pavement stores. Anonymous fields follow the exact existing
    Separate Geometry selection. No boundary is resampled or renumbered.
    """
    index=g.node('GeometryNodeInputIndex').outputs[0]
    points=g.node('GeometryNodeCaptureAttribute','Capture original pavement vertex identity')
    points.domain='POINT';points.capture_items.clear()
    points.capture_items.new('INT','Original vertex')
    g.bind(pavement,points.inputs['Geometry']);g.bind(index,points.inputs['Original vertex'])
    edges=g.node('GeometryNodeCaptureAttribute','Capture original adjacent face ownership')
    edges.domain='EDGE';edges.capture_items.clear()
    g.bind(points.outputs['Geometry'],edges.inputs['Geometry'])
    values=[('Kind',c.named(g,'st_cn_kind','INT')),('Owner',c.named(g,'st_cn_owner','INT'))]
    if original_edge:values.append(('Original edge',index))
    for name,value in values:
        edges.capture_items.new('INT',name);g.bind(value,edges.inputs[name])
    uses=g.node('GeometryNodeInputMeshEdgeNeighbors')
    wire=_edges(g,edges.outputs['Geometry'],g.math('COMPARE',uses.outputs['Face Count'],1.))
    wire=c._store(g,wire,'st_sb_original_vertex',points.outputs['Original vertex'],'INT')
    for name,key in (('Kind','st_sb_kind'),('Owner','st_sb_owner')):
        wire=g.store(wire,key,edges.outputs[name],'EDGE','INT')
    if original_edge:wire=g.store(wire,'st_sr_original_edge',edges.outputs['Original edge'],'EDGE','INT')
    return wire


def build(*, capture_wire=False):
    name=NAME+(' / Captured wire tags' if capture_wire else '')
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    for name in ('Pavement', 'Corridors', 'Mouths'):
        g.socket(name, 'NodeSocketGeometry')
    for name in ('Member A', 'Member B', 'Head Patch', 'Tail Patch'):
        g.socket(name, 'NodeSocketInt')
    for name in ('Boundary', 'Side A', 'Side B', 'Head', 'Tail', 'Diagnostics'):
        g.socket(name, 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    if capture_wire:
        wire=captured_wire(g,inp.outputs['Pavement'])
    else:
        pavement = c._store(g, inp.outputs['Pavement'], 'st_sb_original_vertex', index, 'INT')
        # Capture on EDGE while the adjacent face still exists. An exposed edge
        # has one incident face, so its owner is exact rather than an average.
        for key in ('kind', 'owner'):
            pavement = g.store(pavement, 'st_sb_'+key, c.named(g, 'st_cn_'+key, 'INT'), 'EDGE', 'INT')
        uses = g.node('GeometryNodeInputMeshEdgeNeighbors')
        wire = _edges(g, pavement, g.math('COMPARE', uses.outputs['Face Count'], 1.))
    corridors = inp.outputs['Corridors']; mouths = inp.outputs['Mouths']
    valid = 1.-g.math('COMPARE', inp.outputs['Member A'], inp.outputs['Member B'])
    valid = valid*(1.-g.math('COMPARE', inp.outputs['Head Patch'], inp.outputs['Tail Patch']))
    owner_rows = []; anchors = []; metrics = {}
    keys = g.separate(c.named(g, '_bridge_key', 'FLOAT_VECTOR'))
    islands = g.node('GeometryNodeInputMeshIsland')
    selected_island = None
    for member in ('A', 'B'):
        match = g.math('COMPARE', c.named(g, 'st_cs_street_id', 'INT'), inp.outputs['Member '+member])
        count = c._stat(g, corridors, match, 'Sum')
        at = c._stat(g, corridors, match*index, 'Sum'); owner_rows.append(at)
        valid = valid*g.math('COMPARE', count, 1.)
        for end in ('start', 'end'):
            port = c._read(g, corridors, 'st_cs_'+end+'_index', at, 'INT')
            found, row = providers._lookup(g, mouths, 'st_cj_input_index', port)
            half = c._read(g, mouths, 'st_cj_half', row, 'INT')
            rank = .5*(half+1.)*c._read(g, mouths, 'st_cs_intervals', row, 'INT')
            anchor = g.math('COMPARE', keys[0], 0.)*g.math('COMPARE', keys[1], port)*g.math('COMPARE', keys[2], rank)
            anchor_count = c._stat(g, wire, anchor, 'Sum')
            island = c._stat(g, wire, anchor*c.V(g, islands.outputs['Island Index']), 'Sum')
            valid = valid*found*g.math('COMPARE', g.math('ABSOLUTE', half), 1.)*g.math('COMPARE', anchor_count, 1.)
            if selected_island is None:
                selected_island = island
            else:
                valid = valid*g.math('COMPARE', island, selected_island)
            anchors.append(anchor)
            metrics[member+'_'+end+'_anchor_count'] = anchor_count
    wire = c._select(g, wire, g.math('COMPARE', islands.outputs['Island Index'], selected_island))
    kind = c.named(g, 'st_sb_kind', 'INT'); owner = c.named(g, 'st_sb_owner', 'INT')
    roles = [g.math('COMPARE', kind, 1.)*g.math('COMPARE', owner, at) for at in owner_rows]
    roles.extend(g.math('COMPARE', kind, 0.)*g.math('COMPARE', owner, inp.outputs[name])
                 for name in ('Head Patch', 'Tail Patch'))
    valid = valid*c._stat(g, wire, g.math('COMPARE', sum(roles), 1.), domain='EDGE')
    neighbors = g.node('GeometryNodeInputMeshVertexNeighbors')
    valid = valid*c._stat(g, wire, g.math('COMPARE', neighbors.outputs['Vertex Count'], 2.))
    valid = valid*g.math('GREATER_THAN', c._count(g, wire), 3.5)
    pieces = {}
    for name, role in zip(('Side A', 'Side B', 'Head', 'Tail'), roles):
        part = _edges(g, wire, role)
        end = g.math('COMPARE', neighbors.outputs['Vertex Count'], 1.)
        degree = g.math('MAXIMUM', end, g.math('COMPARE', neighbors.outputs['Vertex Count'], 2.))
        connected = g.math('COMPARE', c._stat(g, part, islands.outputs['Island Count'], 'Max'), 1.)
        count = c._count(g, part)
        valid = valid*connected*c._stat(g, part, degree)*g.math('COMPARE', c._stat(g, part, end, 'Sum'), 2.)
        valid = valid*g.math('GREATER_THAN', count, 1.5)
        pieces[name] = part; metrics[name.lower().replace(' ', '_')+'_vertices'] = count
    record = c._line(g, 1)
    for name, value in metrics.items():
        record = c._store(g, record, 'st_sb_'+name, value, 'INT')
    record = c._store(g, record, 'st_sb_valid', valid, 'BOOLEAN')
    for name, geometry in dict(Boundary=wire, **pieces).items():
        g.bind(boundary._empty(g, geometry, valid), out.inputs[name])
    g.bind(valid, out.inputs['Valid']); g.bind(record, out.inputs['Diagnostics'])
    return g.g
